∀ {α : Type u_1} {β : Type (max u_2 u_3)} {γ : Type} {m : MeasurableSpace α} {μ : Measure α}
  [inst : NormedAddCommGroup β] [inst_1 : NormedAddCommGroup γ] {f : α → β} {g : α → γ},
  HasFiniteIntegral g μ → (∀ᵐ (a : α) ∂μ, ‖f a‖ ≤ ‖g a‖) → HasFiniteIntegral f μ

∀ {α : Type u_1} {β : Type u_7} {m : MeasurableSpace α} {μ : Measure α} [inst : NormedAddCommGroup β] {𝕜 : Type u_7}
  [inst_1 : NormedRing 𝕜] [inst_2 : Module 𝕜 β] [IsBoundedSMul 𝕜 β] {f : α → β} {φ : α → 𝕜},
  Integrable f μ → ∀ (C : ℝ), AEStronglyMeasurable φ μ → (∀ᵐ (a : α) ∂μ, ‖φ a‖ ≤ C) → Integrable (φ • f) μ

